export const COMPENDIUM_VERITE_LOGES_MAGES_PNJ_ARTICLES = [{"id":"pnj-loges-mages-dana-obryan-01","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Daghain","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Loge de New-York","Gouvernement","Mages"],"pnj":{"completeness":"detailed","real_name":"Dana O’BRYAN","nom_verite":"Daghain MELDEGRYN","race":"Mages","age":"«26 ans » - ????","origine":"Américaine","statut":"Gouvernement","affiliations":"Gouvernement","mageius_type":"Kaharal","magie_dominante":"Architetramancie (élémentarisme)","magie_familiale":"Magie sismique","source_group":"Mages","loge":"Loge de New-York","identity_keys":["Daghain","Dana O’BRYAN","Daghain MELDEGRYN"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Dana O’BRYAN"],["Nom de la Vérité","Daghain MELDEGRYN"],["Loge","Loge de New-York"],["Âge","«26 ans » - ????"],["Affiliations","Gouvernement"],["Nationalité d’origine","Américaine"],["Nature réelle","Mages"],["Type de Mageius","Kaharal"],["Magie dominante","Architetramancie (élémentarisme)"],["Magie familiale","Magie sismique"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"De tous les Mages, après l’Archimage, il existe un nom qui résonne dans la Vérité : un nom qui provoque des tremblements chez nombre d’expatriés et de la rage chez d’autres ; un nom que les Atlantes détestent au moins autant que Sil’elaith ; un nom que les vampires anciens veulent voir mort… celui de Daghain MELDEGRYN, la Mage la plus spéciste de la Terre."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-kai-gehrman-02","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Saint-Germain","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Loge de New-York","« Corporatiste »","Mages"],"pnj":{"completeness":"detailed","real_name":"Kai Gehrman","nom_verite":"Saint-Germain","race":"Mages","age":"«44 ans », ????","origine":"Allemande","statut":"« Corporatiste »","affiliations":"« Corporatiste »","mageius_type":"Elinaeth","magie_dominante":"Chronomancie","magie_familiale":"Magie du Retour","source_group":"Mages","loge":"Loge de New-York","identity_keys":["Saint-Germain","Kai Gehrman"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Kai Gehrman"],["Nom de la Vérité","Saint-Germain"],["Loge","Loge de New-York"],["Âge","«44 ans », ????"],["Affiliations","« Corporatiste »"],["Nationalité d’origine","Allemande"],["Nature réelle","Mages"],["Type de Mageius","Elinaeth"],["Magie dominante","Chronomancie"],["Magie familiale","Magie du Retour"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"Gehrman est l’un des Mages les plus puissants siégeant dans une Loge. Il maîtrise principalement la chronomancie, la magie du temps. Ses pairs lui ont tatoué les avant-bras pour lui interdire d’aller physiquement dans le futur ou, pire encore, dans le passé : il a déjà provoqué de graves troubles en modifiant le continuum espace-temps. Les Mages comme les Dieux ne subissant pas les modifications d’une altération temporelle, il a été sévèrement puni sur Terre."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-nina-le-guellec-03","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Viviane","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Loge de New-York","« Corporatiste »","Mages"],"pnj":{"completeness":"detailed","real_name":"Nina Le Guellec","nom_verite":"Fée Viviane – Dame du lac","race":"Mages","age":"«50 ans », ????","origine":"Française","statut":"« Corporatiste »","affiliations":"« Corporatiste »","mageius_type":"Discella","magie_dominante":"Magie des illusions","magie_familiale":"Magie des légendes","source_group":"Mages","loge":"Loge de New-York","identity_keys":["Viviane","Nina Le Guellec","Fée Viviane – Dame du lac"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Nina Le Guellec"],["Nom de la Vérité","Fée Viviane – Dame du lac"],["Loge","Loge de New-York"],["Âge","«50 ans », ????"],["Affiliations","« Corporatiste »"],["Nationalité d’origine","Française"],["Nature réelle","Mages"],["Type de Mageius","Discella"],["Magie dominante","Magie des illusions"],["Magie familiale","Magie des légendes"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"La fée Viviane des légendes, la Dame du Lac, est bien une Mage qui a existé et existe encore. Officiellement française, elle est directrice de branche de la Tuatha. Elle a toujours été une loyale partisane de Morgane (Morrighan) et de Merlin, dont la mort fut un traumatisme profond. Sa magie maîtresse reste celle des illusions, mais à un niveau tel que sa « Magie des légendes » peut rendre concrets des objets ou des créatures issus d’une légende, en proportion du nombre de personnes connaissant cette légende."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-morgane-o-broin-04","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Morgane","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Loge de New-York","« Mafia irlandaise »","Mages - en vérité divine"],"pnj":{"completeness":"detailed","real_name":"Morgane O Broin","nom_verite":"Fée Morgane - Morrighan","race":"Mages - en vérité divine","age":"«40 ans », ????","origine":"Irlandaise","statut":"« Mafia irlandaise »","affiliations":"« Mafia irlandaise »","mageius_type":"Mestherak","magie_dominante":"Magie spectrale","magie_familiale":"Cycle des corneilles","source_group":"Mages","loge":"Loge de New-York","identity_keys":["Morgane","Morgane O Broin","Fée Morgane - Morrighan"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Morgane O Broin"],["Nom de la Vérité","Fée Morgane - Morrighan"],["Loge","Loge de New-York"],["Âge","«40 ans », ????"],["Affiliations","« Mafia irlandaise »"],["Nationalité d’origine","Irlandaise"],["Nature réelle","Mages - en vérité divine"],["Type de Mageius","Mestherak"],["Magie dominante","Magie spectrale"],["Magie familiale","Cycle des corneilles"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"Sous cette identité, Morrighan est « Morgane », la fée des légendes : une Mage d’une puissance et d’une importance colossales. Elle fonda la Loge irlandaise puis la Loge britannique à Londres. Avec le héros Arthur, elle eut Mordred, Mage et chevalier, mais aussi Morfydd, une Mage ressemblant beaucoup à Morrighan. Mortellement blessée, Morfydd s’accrocha à son Mageius. Désormais corneille de Morrighan, elle est le « Mageius » que les Mages sentent en regardant Morgane, bien que la déesse n’en ait pas besoin pour faire de la magie. Loin de suivre les légendes arthuriennes, les événements liés à la véritable Table ronde sont méconnus : on sait que Mordred, semi-dieu, Mage et chevalier, a défié les autres, mais ses raisons restent indéterminées. Sa lignée donna notamment celle des Wright, dont Leslie descend. Souvent, Morfydd remplace sa mère grâce aux illusions de Viviane. En tant que Mage, Morrighan est marchande d’armes pour la mafia irlandaise, vendant étrangement des armes de Raven…"}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-arash-ostaan-05","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Ostanès XII","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Loge de New-York","« Gouvernement »","Mages"],"pnj":{"completeness":"detailed","real_name":"Arash Osta'An","nom_verite":"Ostanès XII","race":"Mages","age":"«62 ans », ????","origine":"iranienne","statut":"« Gouvernement »","affiliations":"« Gouvernement »","mageius_type":"Meldir","magie_dominante":"Sceaux","magie_familiale":"Nécromancie martiale","source_group":"Mages","loge":"Loge de New-York","identity_keys":["Ostanès XII","Arash Osta'An"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Arash Osta'An"],["Nom de la Vérité","Ostanès XII"],["Loge","Loge de New-York"],["Âge","«62 ans », ????"],["Affiliations","« Gouvernement »"],["Nationalité d’origine","iranienne"],["Nature réelle","Mages"],["Type de Mageius","Meldir"],["Magie dominante","Sceaux"],["Magie familiale","Nécromancie martiale"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"Ostanès Ier était un Mage sous Xerxès Ier. Il s’agissait d’un véritable Mage, même s’il faisait passer ses arts pour une forme de science. On le disait nécromancien et devin ; sa véritable force résidait cependant dans l’usage des sceaux et des enchantements, dont il se servait notamment sur l’équipement perse. Onze Ostanès se sont succédé jusqu’à celui-ci. Contrairement à bien des Mages, les Ostanès scellent leur mémoire dans leur Mageius : ils finissent ainsi par partager la même personnalité et les mêmes aspirations. La « nécromancie martiale » combine sceaux et nécromancie. Ostanès XII travaille actuellement pour un centre de recherche gouvernemental des États-Unis à New York."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-gwendoleen-macguire-06","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Gwenddydd","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Loge de New-York","« corporation »","Mages"],"pnj":{"completeness":"detailed","real_name":"Gwendoleen MacGuire","nom_verite":"Gwenddydd","race":"Mages","age":"« 32 ans », ????","origine":"britannique","statut":"« corporation »","affiliations":"« corporation »","mageius_type":"Mestherak","magie_dominante":"magie du sang","magie_familiale":"Atavisme magique","source_group":"Mages","loge":"Loge de New-York","identity_keys":["Gwenddydd","Gwendoleen MacGuire"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Gwendoleen MacGuire"],["Nom de la Vérité","Gwenddydd"],["Loge","Loge de New-York"],["Âge","« 32 ans », ????"],["Affiliations","« corporation »"],["Nationalité d’origine","britannique"],["Nature réelle","Mages"],["Type de Mageius","Mestherak"],["Magie dominante","magie du sang"],["Magie familiale","Atavisme magique"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"Dans certaines légendes galloises, Myrddin — Merlin — a une sœur nommée Gwenddydd. Cette femme est depuis longtemps une Mage de la Loge britannique. Les légendes arthuriennes ne l’ont pas réellement conservée comme magicienne et ont plutôt tendance à la confondre avec la reine Guenièvre, alors qu’elle n’a jamais été reine. Bien qu’elle ne possède pas un Mageius d’Anahita, elle fut une prodigieuse disciple de Morrighan. Durant le Xe siècle, on la surnomma la « calamité des lignées », car elle stérilisait les Mages qui refusaient de se soumettre à elle. Sa magie familiale, l’« Atavisme magique », lui permet d’exprimer n’importe quelle capacité de l’un de ses ancêtres. Comme Merlin, elle descendrait notamment de dragons selon les légendes. Outre cette magie, c’est une grande invocatrice."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-cylia-patra-07","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Circé","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Loge de Los Angeles","« corporatiste »","Mages/ voyageurs"],"pnj":{"completeness":"detailed","real_name":"Cylia PATRA","nom_verite":"Circé","race":"Mages/ voyageurs","age":"«51 ans », ????","origine":"Grecque","statut":"« corporatiste »","affiliations":"« corporatiste »","mageius_type":"Kaharal","magie_dominante":"Morphomancie","magie_familiale":"reprogrammation génétique","source_group":"Mages","loge":"Loge de Los Angeles","identity_keys":["Circé","Cylia PATRA"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Cylia PATRA"],["Nom de la Vérité","Circé"],["Loge","Loge de Los Angeles"],["Âge","«51 ans », ????"],["Affiliations","« corporatiste »"],["Nationalité d’origine","Grecque"],["Nature réelle","Mages/ voyageurs"],["Type de Mageius","Kaharal"],["Magie dominante","Morphomancie"],["Magie familiale","reprogrammation génétique"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"Circé est une Mage assez ancienne, née d’une Amazone — une Voyageuse — et du dieu Lucifer. Elle n’est donc pas parfaitement humaine malgré ses apparences et dispose, même sans ses pouvoirs, d’une redoutable force physique héritée de sa mère. La Grecque est toutefois bien mieux connue pour ses dons de métamorphose : elle maîtrise à la fois les illusions et les véritables déformations du corps. Poussée très loin, sa magie lui permet de réécrire l’ADN de tous les êtres dans son champ de vision ; elle peut littéralement transformer des humains en pourceaux de manière définitive."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-alicia-gullveig-08","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Gullveig","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Loge de Los Angeles","Crawlers","Mages"],"pnj":{"completeness":"detailed","real_name":"Alicia GULLVEIG","nom_verite":"Gullveig","race":"Mages","age":"«24 ans » , ????","origine":"Suédoise","statut":"Crawlers","affiliations":"Crawlers","mageius_type":"Kaharal","magie_dominante":"Alchimie","magie_familiale":"Fusion atomique","source_group":"Mages","loge":"Loge de Los Angeles","identity_keys":["Gullveig","Alicia GULLVEIG"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Alicia GULLVEIG"],["Nom de la Vérité","Gullveig"],["Loge","Loge de Los Angeles"],["Âge","«24 ans » , ????"],["Affiliations","Crawlers"],["Nationalité d’origine","Suédoise"],["Nature réelle","Mages"],["Type de Mageius","Kaharal"],["Magie dominante","Alchimie"],["Magie familiale","Fusion atomique"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"La Mage éponyme n’est certainement pas étrangère à cette légende. Magicienne versée dans la chimie, elle assemble et défait des molécules et, lorsqu’elle pousse sa magie dans ses retranchements, peut aller jusqu’à la fusion et à la fission nucléaires. Elle peut ainsi littéralement transformer de la matière en or en fusionnant les atomes jusqu’à obtenir la bonne densité : le rêve de tous les alchimistes, ses lointains disciples. C’est de fait l’une des Mages les plus puissantes, même si la portée de sa magie reste extrêmement restreinte compte tenu de l’intensité nécessaire."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-naalnish-09","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Nankil’slas","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Loge de Los Angeles","« Corporatiste »","Esprit (mais se fait passer pour un mage)"],"pnj":{"completeness":"detailed","real_name":"Naalnish","nom_verite":"Nankil’slas","race":"Esprit (mais se fait passer pour un mage)","age":"«38 ans », ????","origine":"Navajo","statut":"« Corporatiste »","affiliations":"« Corporatiste »","mageius_type":"Discella (volé et non attaché)","magie_dominante":"Magie des ténèbres","magie_familiale":"la création de deimons corneilles","source_group":"Mages","loge":"Loge de Los Angeles","identity_keys":["Naalnish","Nankil’slas"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Naalnish"],["Nom de la Vérité","Nankil’slas"],["Loge","Loge de Los Angeles"],["Âge","«38 ans », ????"],["Affiliations","« Corporatiste »"],["Nationalité d’origine","Navajo"],["Nature réelle","Esprit (mais se fait passer pour un mage)"],["Type de Mageius","Discella (volé et non attaché)"],["Magie dominante","Magie des ténèbres"],["Magie familiale","la création de deimons corneilles"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"Naalnish siège comme Mage à la Loge de Los Angeles. En vérité, il est une sorte d’électron libre parmi les corneilles de Morrighan : tantôt loyal, tantôt relativement indépendant, ce descendant de Kelta se considère comme un dieu d’importance. Il a volé un Mageius et l’a fait prisonnier de son âme ; cette astuce trompe généralement les Mages et personne d’autre que lui n’a réussi à la reproduire jusqu’ici. Il n’a pas accès au Mageius lui-même, mais dispose de pouvoirs totalement cohérents avec cette couverture."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-zhao-guanyu-10","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Zhu Bajie II","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Loge de Los Angeles","« mafia »","Mages"],"pnj":{"completeness":"detailed","real_name":"Zhao Guanyu","nom_verite":"Zhu Bajie II","race":"Mages","age":"«47 ans », ????","origine":"chinoise","statut":"« mafia »","affiliations":"« mafia »","mageius_type":"Kaharal","magie_dominante":"Morphomancie","magie_familiale":"métamorphose","source_group":"Mages","loge":"Loge de Los Angeles","identity_keys":["Zhu Bajie II","Zhao Guanyu"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Zhao Guanyu"],["Nom de la Vérité","Zhu Bajie II"],["Loge","Loge de Los Angeles"],["Âge","«47 ans », ????"],["Affiliations","« mafia »"],["Nationalité d’origine","chinoise"],["Nature réelle","Mages"],["Type de Mageius","Kaharal"],["Magie dominante","Morphomancie"],["Magie familiale","métamorphose"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"Portant le nom du général céleste devenu porc mangeur de chair dans le conte des pérégrinations vers l’est, ce Mage est un maître du polymorphisme. Il peut devenir grand ou petit, hideux ou beau, humain ou animal, en adoptant la densité et la masse correspondantes. Circé et lui partagent la même magie dominante, mais l’emploient très différemment : Zhu Bajie II se remanie toujours temporairement et principalement lui-même, tandis que Circé altère surtout le corps des autres et peut le faire de manière définitive."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-anayah-kumba-11","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Doussou Damba","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Loge de Los Angeles","« chasseurs »","Mages"],"pnj":{"completeness":"detailed","real_name":"Anayah Kumba","nom_verite":"Doussou Damba","race":"Mages","age":"«42 ans », ????","origine":"Malienne","statut":"« chasseurs »","affiliations":"« chasseurs »","mageius_type":"Meldir","magie_dominante":"Guérison","magie_familiale":"magie des 12","source_group":"Mages","loge":"Loge de Los Angeles","identity_keys":["Doussou Damba","Anayah Kumba"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Anayah Kumba"],["Nom de la Vérité","Doussou Damba"],["Loge","Loge de Los Angeles"],["Âge","«42 ans », ????"],["Affiliations","« chasseurs »"],["Nationalité d’origine","Malienne"],["Nature réelle","Mages"],["Type de Mageius","Meldir"],["Magie dominante","Guérison"],["Magie familiale","magie des 12"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"La légende de Doussou Damba daterait du XIIIe siècle. Elle présidait la Loge de Mandé, un royaume, à la tête de onze Mages décrites comme de puissantes sorcières. Doussou est une maîtresse de la guérison, voire de la véritable résurrection. Elle ne peut cependant pas réellement créer la vie et a besoin de sacrifices pour cela, raison pour laquelle on la décrivait comme anthropophage. Cette beauté africaine a vécu longtemps, errant de Loge en Loge après le massacre de la sienne. Elle est la grande rivale de Makeda et l’une des « Trois grandes maîtresses », aux côtés de Makeda, à l’est, et d’une Mage du sud de l’Afrique, dans la région des Grands Lacs. À l’époque moderne, elle fut membre du PCRC, où elle dirigeait la section chimique. Elle cacha son Mageius en raison de la présence d’Amazones et de Dives aux côtés de Katja. Elle disparut après la guerre. Souvent absente de la Loge, elle met fréquemment en colère sa femme, Circé, en disparaissant pendant des semaines ; Doussou cherche éternellement les Mageius de ses onze sœurs, massacrées par un Dive."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-sergio-venegas-12","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Siamak Faghih","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Loge de Los Angeles","« crawlers : gundrivers »","Mages"],"pnj":{"completeness":"detailed","real_name":"Sergio Venegas","nom_verite":"Siamak Faghih","race":"Mages","age":"«24 ans », ????","origine":"Mexicaine","statut":"« crawlers : gundrivers »","affiliations":"« crawlers : gundrivers »","mageius_type":"Meldir","magie_dominante":"Sceaux","magie_familiale":"Magie des poches","source_group":"Mages","loge":"Loge de Los Angeles","identity_keys":["Siamak Faghih","Sergio Venegas"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Sergio Venegas"],["Nom de la Vérité","Siamak Faghih"],["Loge","Loge de Los Angeles"],["Âge","«24 ans », ????"],["Affiliations","« crawlers : gundrivers »"],["Nationalité d’origine","Mexicaine"],["Nature réelle","Mages"],["Type de Mageius","Meldir"],["Magie dominante","Sceaux"],["Magie familiale","Magie des poches"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"Jamais cité dans les légendes de Sinbad le marin, Siamak était pourtant l’un des compagnons de l’aventurier et a bel et bien existé. Le Mage était avant tout marchand, collectionneur et dresseur. L’essentiel de sa magie consistait à sceller des objets dans des espaces infiniment petits pour les déstocker ailleurs. Il n’a jamais été un Mage surpuissant, mais sa collection compense largement son manque de pouvoir. De tous les maîtres des Loges, il est le seul à ne posséder qu’une affinité et à avoir renoncé à presque toutes les magies en dehors de celle de prédilection. Ce maître des sceaux aurait cependant dans sa collection d’anciens Fléaux mineurs ainsi que des armes divines…"}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-mickael-date-13","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Mithridate","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Loge de San Diejuana","« crawlers : neopunks»","Mages"],"pnj":{"completeness":"detailed","real_name":"Mickael DATE","nom_verite":"Mithridate","race":"Mages","age":"«68 ans », ????","origine":"???","statut":"« crawlers : neopunks»","affiliations":"« crawlers : neopunks»","mageius_type":"Kaharal","magie_dominante":"Alchimie","magie_familiale":"Magie des poisons","source_group":"Mages","loge":"Loge de San Diejuana","identity_keys":["Mithridate","Mickael DATE"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Mickael DATE"],["Nom de la Vérité","Mithridate"],["Loge","Loge de San Diejuana"],["Âge","«68 ans », ????"],["Affiliations","« crawlers : neopunks»"],["Nationalité d’origine","???"],["Nature réelle","Mages"],["Type de Mageius","Kaharal"],["Magie dominante","Alchimie"],["Magie familiale","Magie des poisons"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"Il aime le conflit et adore plus encore l’époque qu’est 2035, où tout fusionne et tout se croise, tout s’ignore et tout cohabite sans aucune structure ni ordre. Sa magie est essentiellement basée sur les poisons, les venins, les drogues et toute substance altérant les corps. Il aime voir ses ennemis perdre lentement leurs facultés physiques et mentales, c’est un grand sadique dont le plus grand rêve est de pisser sur la foule de croyants du haut de la tour Vatican."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-adrien-daigremont-14","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Maugis","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Loge de San Diejuana","« Crawler : Deathrunner »","Mages"],"pnj":{"completeness":"detailed","real_name":"Adrien d’Aigremont","nom_verite":"Maugis","race":"Mages","age":"«33 ans », ????","origine":"française","statut":"« Crawler : Deathrunner »","affiliations":"« Crawler : Deathrunner »","mageius_type":"Elinaeth","magie_dominante":"Télékinésie","magie_familiale":"Invisible chevalerie","source_group":"Mages","loge":"Loge de San Diejuana","identity_keys":["Maugis","Adrien d’Aigremont"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Adrien d’Aigremont"],["Nom de la Vérité","Maugis"],["Loge","Loge de San Diejuana"],["Âge","«33 ans », ????"],["Affiliations","« Crawler : Deathrunner »"],["Nationalité d’origine","française"],["Nature réelle","Mages"],["Type de Mageius","Elinaeth"],["Magie dominante","Télékinésie"],["Magie familiale","Invisible chevalerie"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"Maugis est l’enchanteur de la légende des quatre fils d’Aymon. Le Mage véritable était un chevalier dès l’époque romaine. Maitre épéiste, ce télékinésiste est capable de générer des lames tranchantes en influençant sur la pesanteur elle-même, c’est un maitre de la pression à distance et sa magie personnelle « invisible chevalerie » lui confère l’équivalent d’une armure ou d’une épée en matière noire soit totalement invisibles. Il lutte férocement contre les cultes de V ‘Aagor, la secte de l’œil blanc notamment, puisque, sans savoir qu’ils sont extraterrestres, les cultistes sont des manieurs de matière noire comme lui. Il s’entend aussi très mal avec les chasseurs de la table ronde, de vils anglois."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-melina-apapoulos-15","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Melinoé","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Loge de San Diejuana","« crawler : freerunners »","Mages"],"pnj":{"completeness":"detailed","real_name":"Melina Apapoulos","nom_verite":"Melinoe « hécate » Skotia","race":"Mages","age":"«30 ans », ????","origine":"grecque","statut":"« crawler : freerunners »","affiliations":"« crawler : freerunners »","mageius_type":"Mestherak","magie_dominante":"Magie spectrale","magie_familiale":"Grotte infernale","source_group":"Mages","loge":"Loge de San Diejuana","identity_keys":["Melinoé","Melina Apapoulos","Melinoe « hécate » Skotia"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Melina Apapoulos"],["Nom de la Vérité","Melinoe « hécate » Skotia"],["Loge","Loge de San Diejuana"],["Âge","«30 ans », ????"],["Affiliations","« crawler : freerunners »"],["Nationalité d’origine","grecque"],["Nature réelle","Mages"],["Type de Mageius","Mestherak"],["Magie dominante","Magie spectrale"],["Magie familiale","Grotte infernale"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"Dans les légendes, Melinoé est la déesse des fantômes et des cauchemars. Cette Dhampire est la fille de Dragoy Skotia, le roi vampirique et d’une femme mage inconnue, maitresse de la mort. Melinoé est la seule Dhampire connue à avoir un Mageius. Elle déteste plus que quiconque sa sœur, Elodie-Katherine dite « Hécate », dont elle vole le nom régulièrement dans la vérité, se faisant aussi appeler ainsi. Maitresse de la magie spectrale et des cauchemars, elle est une ennemie farouche des vampires, ces derniers l’ayant rejetée."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-adalardo-gravina-16","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Autolycos","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Loge de San Diejuana","« crawler : cyberthugs»","Mages"],"pnj":{"completeness":"detailed","real_name":"Adalardo Gravina","nom_verite":"Autolycos","race":"Mages","age":"«34 ans », ????","origine":"Italienne","statut":"« crawler : cyberthugs»","affiliations":"« crawler : cyberthugs»","mageius_type":"Elinaeth","magie_dominante":"magie temporelle","magie_familiale":"téléportation","source_group":"Mages","loge":"Loge de San Diejuana","identity_keys":["Autolycos","Adalardo Gravina"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Adalardo Gravina"],["Nom de la Vérité","Autolycos"],["Loge","Loge de San Diejuana"],["Âge","«34 ans », ????"],["Affiliations","« crawler : cyberthugs»"],["Nationalité d’origine","Italienne"],["Nature réelle","Mages"],["Type de Mageius","Elinaeth"],["Magie dominante","magie temporelle"],["Magie familiale","téléportation"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"Autolycos est connu dans la mythologie grecque comme étant le plus grand voleur, fils de Hermès et ancêtre d’Ulysse, selon les légendes. S’il faut retenir des légendes quelque chose c’est que c’est effectivement un voleur, le meilleur selon lui, un beau parleur aussi séducteur que trompeur. Il utilise la magie temporelle pour réduire les distances et être insaisissable. On le dit fou amoureux de Daghain et détesté mortellement par Circé, raison pour laquelle la loge de Diejuana n’est pas aisément alliée à Los Angeles face à New-York."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-zephia-brummer-17","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Zephania","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Loge de San Diejuana","« crawlers : neopunks »","Mages"],"pnj":{"completeness":"detailed","real_name":"Zephia Brummer","nom_verite":"Zephania – la sorcière d’Endor","race":"Mages","age":"«34 ans », ????","origine":"Israélienne","statut":"« crawlers : neopunks »","affiliations":"« crawlers : neopunks »","mageius_type":"Mestherak","magie_dominante":"Nécromancie","magie_familiale":"Nécromancie divinatoire","source_group":"Mages","loge":"Loge de San Diejuana","identity_keys":["Zephania","Zephia Brummer","Zephania – la sorcière d’Endor"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Zephia Brummer"],["Nom de la Vérité","Zephania – la sorcière d’Endor"],["Loge","Loge de San Diejuana"],["Âge","«34 ans », ????"],["Affiliations","« crawlers : neopunks »"],["Nationalité d’origine","Israélienne"],["Nature réelle","Mages"],["Type de Mageius","Mestherak"],["Magie dominante","Nécromancie"],["Magie familiale","Nécromancie divinatoire"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"« La Sorcière d’Endor » dans la Bible est une sorcière qui invoqua le prophète Samuel sur demande du roi Saul. La véritable Mage est bien une nécromancienne mais elle n’est désormais que peu amie avec les religieux. Elle utilise essentiellement les spectres plutôt que les cadavres et maitrise la magie spectrale, évidemment. Elle est la plus proche alliée de Mithridate dans sa lutte pour préserver la loge de Diejuana face à Los Angeles cependant, elle est plus ouverte à négocier avec Circé pour contrer Daghain."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-shane-rosenberg-18","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Shane Rosenberg","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Loge de San Diejuana","« crawlers : cypper »","Mages -nephilim"],"pnj":{"completeness":"detailed","real_name":"Shane Rosenberg","nom_verite":"Elyon","race":"Mages -nephilim","age":"«38 ans », ????","origine":"américaine","statut":"« crawlers : cypper »","affiliations":"« crawlers : cypper »","mageius_type":"Meldir","magie_dominante":"magie lumineuse","magie_familiale":"Magie angélique","source_group":"Mages","loge":"Loge de San Diejuana","identity_keys":["Shane Rosenberg","Elyon"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Shane Rosenberg"],["Nom de la Vérité","Elyon"],["Loge","Loge de San Diejuana"],["Âge","«38 ans », ????"],["Affiliations","« crawlers : cypper »"],["Nationalité d’origine","américaine"],["Nature réelle","Mages -nephilim"],["Type de Mageius","Meldir"],["Magie dominante","magie lumineuse"],["Magie familiale","Magie angélique"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"Shane est un cypper, c’est-à-dire un crawler qui est spécialisé dans le sabotage et les pièges, il n’est pas spécialement connu dans la Californie et n’opère qu’à San Diejuana généralement. C’est un très ancien mage néanmoins. Nommé Elyon, c’est un fils de Camaelle qu’elle eut avec un humain. Mage de lumière et de foudre, ce nephilim est l’un des rares à avoir un Mageius. Il a développé par haine de ses origines la « magie angélique », reproduisant tous les pouvoirs des anges existants ainsi que la transcendance, c’est lui qui, autrefois, confectionna les arts kabbalistes des chasseurs hébraïques. Détesté des anges, sa magie dévore leurs pouvoirs, c’ets pourquoi san Diejuana est assez délaissée comme ville par les Cieux."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-mada-oromo-nerayo-19","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Makeda","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Loge de Las Vegas","« crawler : meditech »","Mages"],"pnj":{"completeness":"detailed","real_name":"Mada Oromo Nerayo","nom_verite":"Makeda – reine de Saba","race":"Mages","age":"«34 ans », ????","origine":"Ethiopienne","statut":"« crawler : meditech »","affiliations":"« crawler : meditech »","mageius_type":"Meldir","magie_dominante":"Guérison","magie_familiale":"Salvation","source_group":"Mages","loge":"Loge de Las Vegas","identity_keys":["Makeda","Mada Oromo Nerayo","Makeda – reine de Saba"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Mada Oromo Nerayo"],["Nom de la Vérité","Makeda – reine de Saba"],["Loge","Loge de Las Vegas"],["Âge","«34 ans », ????"],["Affiliations","« crawler : meditech »"],["Nationalité d’origine","Ethiopienne"],["Nature réelle","Mages"],["Type de Mageius","Meldir"],["Magie dominante","Guérison"],["Magie familiale","Salvation"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"Mada est Makeda, la « reine de Saba » de la bible. Grande Mage, elle a longtemps régné seule sur les loges Ethiopiennes et alentours. Bien que Crawler indépendante, travaillant souvent avec Elizabeth Karnstein, elle serait la mère naturelle de Keysha Richards, qu’elle abandonna pour ne pas l’exposer à la lutte des Loges. C’est la présidente de la loge de Las Vegas actuellement, elle a pris les « rois Mages » avec elles. Sa magie « Salvation », déchire les malédictions, effets magiques et le marquage divin ou démoniaque, pouvant faire d’un ange un simple spectre en le purgeant."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-mertkan-sabanci-20","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Melchior","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Loge de Las Vegas","« Corporatiste »","Mages"],"pnj":{"completeness":"detailed","real_name":"Mertkan Sabanci","nom_verite":"Melchior –(Melekoth)","race":"Mages","age":"«48 ans », ????","origine":"turque","statut":"« Corporatiste »","affiliations":"« Corporatiste »","mageius_type":"Elinaeth","magie_dominante":"Télékinésie","magie_familiale":"Contrôle mental","source_group":"Mages","loge":"Loge de Las Vegas","identity_keys":["Melchior","Mertkan Sabanci","Melchior –(Melekoth)"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Mertkan Sabanci"],["Nom de la Vérité","Melchior –(Melekoth)"],["Loge","Loge de Las Vegas"],["Âge","«48 ans », ????"],["Affiliations","« Corporatiste »"],["Nationalité d’origine","turque"],["Nature réelle","Mages"],["Type de Mageius","Elinaeth"],["Magie dominante","Télékinésie"],["Magie familiale","Contrôle mental"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"Melchior est le roi-mage de la Bible. Toutefois, c’était loin d’être ce que le saint livre en fait. Roi tyrannique refusant toute loge dans son territoire, c’était un des trois rois- mages de l’époque avec les célèbres Balthazar et Gaspard. Les trois se disputaient le « trône de jerusalem », non pas le titre royal mais bien l’objet, qui recelait un Mageius, quiconque siégeant dessus pouvant l’utiliser. maitre de la télépathie Melchior était le plus riche des trois et celui avec la plus grande armée de fidèles."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-bassaam-el-akram-21","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Balthazar","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Loge de Las Vegas","« Corporatiste »","Mages"],"pnj":{"completeness":"detailed","real_name":"Bassaam el-Akram","nom_verite":"Balthazar (Baal Al’Tazeem)","race":"Mages","age":"«54 ans », ????","origine":"Arabe","statut":"« Corporatiste »","affiliations":"« Corporatiste »","mageius_type":"Elinaeth","magie_dominante":"Divination","magie_familiale":"Prophétie invasive","source_group":"Mages","loge":"Loge de Las Vegas","identity_keys":["Balthazar","Bassaam el-Akram","Balthazar (Baal Al’Tazeem)"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Bassaam el-Akram"],["Nom de la Vérité","Balthazar (Baal Al’Tazeem)"],["Loge","Loge de Las Vegas"],["Âge","«54 ans », ????"],["Affiliations","« Corporatiste »"],["Nationalité d’origine","Arabe"],["Nature réelle","Mages"],["Type de Mageius","Elinaeth"],["Magie dominante","Divination"],["Magie familiale","Prophétie invasive"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"Baal Al’Tazeem de son vrai nom était un roi de la péninsule arabique. Tout comme Melekoth le perse, c’était un tyran régnant sans partage par sa Magie. Maitre de la divination, il prévoyait et contrait tos les plans ennemis, grand stratège de plus. Son véritable atout était sa magie familiale, ses prophéties invasives se réalisaient, prophéties purement fictives à la base que sa magie rendait concrète. Convoitant l’artefact qu’était le « trône magique », il s’opposa aux deux autres rois-Mages dans une guerre sanglante."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-hassan-abate-yideg-22","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Gaspard","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Loge de Las Vegas","« Corporatiste »","Mages"],"pnj":{"completeness":"detailed","real_name":"Hassan Abate Yideg","nom_verite":"Gaspard – (Kazeem Balar)","race":"Mages","age":"«34 ans », ????","origine":"Ethiopienne","statut":"« Corporatiste »","affiliations":"« Corporatiste »","mageius_type":"Elinaeth","magie_dominante":"magie temporelle","magie_familiale":"Salvation","source_group":"Mages","loge":"Loge de Las Vegas","identity_keys":["Gaspard","Hassan Abate Yideg","Gaspard – (Kazeem Balar)"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Hassan Abate Yideg"],["Nom de la Vérité","Gaspard – (Kazeem Balar)"],["Loge","Loge de Las Vegas"],["Âge","«34 ans », ????"],["Affiliations","« Corporatiste »"],["Nationalité d’origine","Ethiopienne"],["Nature réelle","Mages"],["Type de Mageius","Elinaeth"],["Magie dominante","magie temporelle"],["Magie familiale","Salvation"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"Gaspard est celui qui a inspiré le roi-mage à la peau sombre. Fils de Makeda, la « reine de Saba », une des trois grandes Magiciennes d’Afrique, il voulait s’emparer du « trône de Jérusalem » pour avoir les dons de divination suffisants pour trouver sa mère, retenue captive quelque part. Roi-mage le plus puissant, il étirait les nuits pour attaquer pendant le sommeil ennemi et sous couvert de la nuit, il ralentissait les troupes adverses aussi et plus redouté encore, il désenvoutait les ennemis d’éventuels sorts les améliorant ou les contrôlant. Bien qu’il soit le fils de Makeda, il possède sa propre famille de mages.Makeda a bien fait attention à lui dissimuler l’existence de Keysha, car elle sait son ainé capable de sombrer dans l’inceste si cela assure d’avoir des enfants mages."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-asuka-yamamuro-23","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Rangda","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Loge de Phoenix","« Crawlers : gunwatcher»","Mages"],"pnj":{"completeness":"detailed","real_name":"Asuka Yamamuro","nom_verite":"Yama-Uba","race":"Mages","age":"«44 ans », ????","origine":"japonaise","statut":"« Crawlers : gunwatcher»","affiliations":"« Crawlers : gunwatcher»","mageius_type":"Kaharal","magie_dominante":"Magie de modelage","magie_familiale":"Carbone vivant","source_group":"Mages","loge":"Loge de Phoenix","identity_keys":["Rangda","Asuka Yamamuro","Yama-Uba"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Asuka Yamamuro"],["Nom de la Vérité","Yama-Uba"],["Loge","Loge de Phoenix"],["Âge","«44 ans », ????"],["Affiliations","« Crawlers : gunwatcher»"],["Nationalité d’origine","japonaise"],["Nature réelle","Mages"],["Type de Mageius","Kaharal"],["Magie dominante","Magie de modelage"],["Magie familiale","Carbone vivant"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"Dans la légende Yama-Uba ou Yamamba est une sorcière à l’apparence hideuse, la bouche aussi large que sa tête, capable de mouvoir sa chevelure comme des serpents. Elle se fait passer pour une jeune et belle jeune femme pour attirer ses victimes. Asuka est le Mage à l’origine de cette légende, polymorphe elle effrayait les gens dans sa montagne pour rester en paix. Sa magie familiale est le « Carbone vivant », alliant alchimie et modelage, elle peut animer toute matière carbonée comme s’il s’agissait d’un être vivant en y insufflant son âme. Elle change de corps régulièrement pour échapper à l’âge. Avec Rangda, elle s’est opposée à Hwang-Gung, en vain, fuyant pour la Californie en voyant la loge de Tokyo anéantie."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-anggriawan-yang-24","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Yama-Uba","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Loge de Phoenix","« Crawler : hookers »","Mages"],"pnj":{"completeness":"detailed","real_name":"Anggriawan Yáng","nom_verite":"Rangda – « reine des Leyaks »","race":"Mages","age":"«26 ans », ????","origine":"Indonésienne","statut":"« Crawler : hookers »","affiliations":"« Crawler : hookers »","mageius_type":"Discella","magie_dominante":"magie des ombres","magie_familiale":"Empire des ombres","source_group":"Mages","loge":"Loge de Phoenix","identity_keys":["Yama-Uba","Anggriawan Yáng","Rangda – « reine des Leyaks »"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Anggriawan Yáng"],["Nom de la Vérité","Rangda – « reine des Leyaks »"],["Loge","Loge de Phoenix"],["Âge","«26 ans », ????"],["Affiliations","« Crawler : hookers »"],["Nationalité d’origine","Indonésienne"],["Nature réelle","Mages"],["Type de Mageius","Discella"],["Magie dominante","magie des ombres"],["Magie familiale","Empire des ombres"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"Rangda est considérée dans le Folklore de Bali comme la reine des démons. C’est une très ancienne magicienne. Elle a créé les Leyak, des deimons la servant elle et elle seule. Amante de Mephisto, elle a toutefois été corrompue par V’Aagor et le Dieu l’a alors rejetée. Elle a été enfermée dans l’Ombre-monde lors de la création de l’Hologramme mais en est récemment sortie. Souvent décrite comme hideuse et effrayante, elle est, au contraire d’une beauté envoutante. En revanche, sa cruauté est redoutable. Pendant la guerre de Corée, les mages en Asie s’affrontèrent et la Loge de Seoul s’est imposée, anéantissant ou soumettant les autres loges de l’extrême Orient. Rangda et d’autres ont alors émigré. La loge de Phoenix est devenue la loge « asiatique »."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-jin-tian-myong-25","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Xingtian","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Loge de Phoenix","« Crawler : Deathrunner»","Mages"],"pnj":{"completeness":"detailed","real_name":"Jin-Tian Myong","nom_verite":"Xingtian","race":"Mages","age":"«42 ans », ????","origine":"Allemande","statut":"« Crawler : Deathrunner»","affiliations":"« Crawler : Deathrunner»","mageius_type":"Meldir","magie_dominante":"Guérison","magie_familiale":"fusion des corps","source_group":"Mages","loge":"Loge de Phoenix","identity_keys":["Xingtian","Jin-Tian Myong"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Jin-Tian Myong"],["Nom de la Vérité","Xingtian"],["Loge","Loge de Phoenix"],["Âge","«42 ans », ????"],["Affiliations","« Crawler : Deathrunner»"],["Nationalité d’origine","Allemande"],["Nature réelle","Mages"],["Type de Mageius","Meldir"],["Magie dominante","Guérison"],["Magie familiale","fusion des corps"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"Xingtian est décrit comme un dieu poursuivant son combat malgré sa propre décapitation, changeant ses tétons en yeux pour voir. Le mage du même nom n’a rien d’un dieu mais est totalement dans cette optique de modification corporelle. Il a altéré le principe de « guérison » pour être le maitre des chimères et des altérations physiques ; Il possède des organes volés à d’autres créatures dans son corps. Pendant la guerre de Corée, il était officiellement un Sud-coréen. Hwang-gung, le plus puissant Mage de Seoul ne le laissa pas s’amuser, il profita de la guerre pour anéantir les loges nord-coréennes, japonaises puis chinoises avant de conquérir une part de l’Asie. Xingtian fut dépecé et jeté mais il fut emporté par Rangda en Californie. Mercenaire désormais, il traque surtout les sorciers de Hwang-gung."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-robert-peng-26","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Shui Peng","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Loge de Phoenix","« Crawlers : meditech»","Mages"],"pnj":{"completeness":"detailed","real_name":"Robert Peng","nom_verite":"Peng Shui","race":"Mages","age":"«51 ans », ????","origine":"américaine","statut":"« Crawlers : meditech»","affiliations":"« Crawlers : meditech»","mageius_type":"Mestherak","magie_dominante":"Necromancie","magie_familiale":"Jiangshi","source_group":"Mages","loge":"Loge de Phoenix","identity_keys":["Shui Peng","Robert Peng","Peng Shui"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Robert Peng"],["Nom de la Vérité","Peng Shui"],["Loge","Loge de Phoenix"],["Âge","«51 ans », ????"],["Affiliations","« Crawlers : meditech»"],["Nationalité d’origine","américaine"],["Nature réelle","Mages"],["Type de Mageius","Mestherak"],["Magie dominante","Necromancie"],["Magie familiale","Jiangshi"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"Shui Peng était le plus puissant nécromancien chinois de toute l’Histoire orientale. Ses douze armées de Jiangshi étaient redoutées et sa magie éponyme leur conférait des capacités surhumaines. On ignore l’époque mais il fut redoutablement vaincu. Emigré aux Etats-Unis durant la conquête de l’Ouest, il a fait son trou avant d’accueillir les ressortissants asiatiques durant la guerre du pacifique de 22-28. Malgré lui, il se retrouva à la Loge de Phoenix dans la guerre opposant cette Loge insignifiante à la base face au mastodonte qu’était celle de Los Angeles. Son dernier fils, Tenggara est issu de son union avec Rangda et a été désigné comme le protecteur de la loge même s’il semble avoir de grandes ambitions."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-roowinu-27","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Glooscap","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Loge de la Grande Réserve","« Corporatiste »","Mages"],"pnj":{"completeness":"detailed","real_name":"Roowinu","nom_verite":"Glooscap","race":"Mages","age":"«41 ans », ????","origine":"americaine (micmacs)","statut":"« Corporatiste »","affiliations":"« Corporatiste »","mageius_type":"Kaharal","magie_dominante":"magie élémentaire","magie_familiale":"gigantisme élémentaire","source_group":"Mages","loge":"Loge de la Grande Réserve","identity_keys":["Glooscap","Roowinu"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Roowinu"],["Nom de la Vérité","Glooscap"],["Loge","Loge de la Grande Réserve"],["Âge","«41 ans », ????"],["Affiliations","« Corporatiste »"],["Nationalité d’origine","americaine (micmacs)"],["Nature réelle","Mages"],["Type de Mageius","Kaharal"],["Magie dominante","magie élémentaire"],["Magie familiale","gigantisme élémentaire"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"Divinité micmac, Glooscap était le « bon » jumeau, un géant bienfaisant maitrisant des pouvoirs de création. C’était le nom que l’on donnait à la divinité belzébuth, le dieu de la Vie chez des peuples natifs. Cependant, un Mage en a décidé autrement, singeant la légende du dieu il s’est imposé comme « LE Glooscap » et s’est fait vénérer en utilisant sa magie pour devenir géant. Naste , la « grand-mère araignée », l’a scellé plusieurs siècles pour lui apprendre l’humilité et le protéger des dieux."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-mike-michabou-28","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Nanabozo","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Loge de la Grande Réserve","« crawler : hooker »","Mages – semi-Esprit"],"pnj":{"completeness":"detailed","real_name":"Mike - « michabou »","nom_verite":"Nanabozo - Michabou","race":"Mages – semi-Esprit","age":"«24 ans », ????","origine":"américaine (Algonquins)","statut":"« crawler : hooker »","affiliations":"« crawler : hooker »","mageius_type":"Elinaeth","magie_dominante":"Divination","magie_familiale":"Reconceptualisation","source_group":"Mages","loge":"Loge de la Grande Réserve","identity_keys":["Nanabozo","Mike - « michabou »","Nanabozo - Michabou"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Mike - « michabou »"],["Nom de la Vérité","Nanabozo - Michabou"],["Loge","Loge de la Grande Réserve"],["Âge","«24 ans », ????"],["Affiliations","« crawler : hooker »"],["Nationalité d’origine","américaine (Algonquins)"],["Nature réelle","Mages – semi-Esprit"],["Type de Mageius","Elinaeth"],["Magie dominante","Divination"],["Magie familiale","Reconceptualisation"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"Nanabozo, le « Grand lièvre », dans la légende c’est un demi-dieu ou un dieu qui est à la fois créateur et à la fois trompeur. Le Mage est né d’un esprit et d’une humaine, comme dans la légende, Le sang de Kelta Lièvre lui donna de fortes affinités avec la magie et il vola le Mageius de sa mère à la naissance. Nanabozo vécu seul, obsédé sexuelle et trompeur, il est un très bon ami de Naalnish, son meilleur ami même, bien qu’il déteste le fait qu’il préfère la loge de Los Angeles à celle de la Réserve. Strip-teaser et prostitué, c’est un crawler qui est très souvent employé par la Tala dans la grande Réserve. Dès que Tokala le voit, elle est irrémédiablement excitée, mais c’est parce que voir un petit lièvre danser peut exciter l’instinct chasseur d’une « louve ». Sa magie est assez redoutable, Reconceptualisation consistant à renommer les choses et en changer le fonctionnement en le prévoyant autrement."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-muna-29","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Naste Estsan- Jorogumo-Arachne","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Loge de la Grande Réserve","« pègre »","Mages"],"pnj":{"completeness":"detailed","real_name":"Muna","nom_verite":"Naste Estsan – Jorogumo- Arachne","race":"Mages","age":"«34 ans », ????","origine":"Américaine (Hopi)","statut":"« pègre »","affiliations":"« pègre »","mageius_type":"Discella","magie_dominante":"Magie des ombres","magie_familiale":"Toile des destins","source_group":"Mages","loge":"Loge de la Grande Réserve","identity_keys":["Naste Estsan- Jorogumo-Arachne","Muna","Naste Estsan – Jorogumo- Arachne"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Muna"],["Nom de la Vérité","Naste Estsan – Jorogumo- Arachne"],["Loge","Loge de la Grande Réserve"],["Âge","«34 ans », ????"],["Affiliations","« pègre »"],["Nationalité d’origine","Américaine (Hopi)"],["Nature réelle","Mages"],["Type de Mageius","Discella"],["Magie dominante","Magie des ombres"],["Magie familiale","Toile des destins"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"Muna est une mafieuse de la grande réserve. Elle est toutefois mieux connue comme « Arachne » ou « Jorogumo » dans les mythes du monde. Sa première occurrence est toutefois « Grand-mère Araignée » chez les natifs américains., une divinité. Le mage à l’origine de ces mythes n’a rien d’une déesse mais cette maitresse des ombres et des malédictions pouvait détruire les destins et possédait une affinité secondaire dans le modelage, pouvant créer des corps d’argile où y enfermer par malédiction des âmes. Elle est connue pour être l’une des Mages les plus douées en artisanat et les habits qu’elle tisse sont toujours d’une puissance magique assez difficile à évaluer."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-lara-steven-30","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Lara Steven","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Loge de la Grande Réserve","« Gouvernement »","Mages"],"pnj":{"completeness":"detailed","real_name":"Lara Steven","nom_verite":"Sokanon","race":"Mages","age":"«24 ans », ????","origine":"Américaine (Wolastoqiyik)","statut":"« Gouvernement »","affiliations":"« Gouvernement »","mageius_type":"Meldir","magie_dominante":"Guérison","magie_familiale":"Synergie vitale","source_group":"Mages","loge":"Loge de la Grande Réserve","identity_keys":["Lara Steven","Sokanon"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Lara Steven"],["Nom de la Vérité","Sokanon"],["Loge","Loge de la Grande Réserve"],["Âge","«24 ans », ????"],["Affiliations","« Gouvernement »"],["Nationalité d’origine","Américaine (Wolastoqiyik)"],["Nature réelle","Mages"],["Type de Mageius","Meldir"],["Magie dominante","Guérison"],["Magie familiale","Synergie vitale"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"Sokanon était une « taoueille » su XVIIème siècle, une sorcière amérindienne, un nom péjoratif le plus souvent. La rencontre avec des occidentaux fut loin d’être comparable à Pocahontas de Disney mais elle resta pacifique, la famille de Sokanon soignant les Français mal nourris et malades, la jeune fille comprit toutefois assez vite que ces maladies touchèrent plus violemment les siens et elle chercha à faire cesser le commerce, se faisant vite mal percevoir des deux camps. Elle devint mage à 17 ans, après avoir été punie pour ses idée et jetée dans un gouffre où un vieux mage cul-de-jatte gisait aussi, elle proposa de prendre ses pouvoirs en échange, elle lui cédait ses jambes et le libérait, le Mage, curieux, accepta et fut tué une fois son Mageius cédé. Sokanon devint une calamité pour les occidentaux. Sa magie personnelleest la synergie vitale, qui plonge dans un état de soin et d’optimum physique tel qu’un simple citoyen rivaliserait avec un athlète olympique."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-edwin-kelly-31","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Edwin kelly","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Autres Loges","« Associatif »","Mages"],"pnj":{"completeness":"detailed","real_name":"Edwin kelly","nom_verite":"Edwin","race":"Mages","age":"«40 ans », 99 ans","origine":"Américain","statut":"« Associatif »","affiliations":"« Associatif »","mageius_type":"Kaharal","magie_dominante":"magie de Modelage","magie_familiale":"Asservissement des bêtes","source_group":"Mages","loge":"Autres Loges","identity_keys":["Edwin kelly","Edwin"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Edwin kelly"],["Nom de la Vérité","Edwin"],["Loge","Autres Loges"],["Âge","«40 ans », 99 ans"],["Affiliations","« Associatif »"],["Nationalité d’origine","Américain"],["Nature réelle","Mages"],["Type de Mageius","Kaharal"],["Magie dominante","magie de Modelage"],["Magie familiale","Asservissement des bêtes"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"La famille Kelly descend des « Meneurs de Loups », notamment français du Berry. Des Mages qui avaient pour pouvoir d’asservir des loups-garous et d’en singer des compétences. Avec la colonisation, la famille s’installa aux Etats-Unis où elle se mêla à des familles de Mage venus d’Afrique, avec l’esclavage. Edwin a moins d’un siècle, cependant, c’est un mage brutal dont la force physique, par sa magie est capable de lui faire lancer des projectiles aussi vites qu’une balle. Il possède des sorcières-chasseuses dotées du sang de loup-garou et lutte contre la Loge d’Ecume."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-mila-shelove-32","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Mila Shelove","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Autres Loges","« crawler : enders»","Mages (fléau mineur)"],"pnj":{"completeness":"detailed","real_name":"Mila Shelove","nom_verite":"Milushka Voroshilov","race":"Mages (fléau mineur)","age":"«46 ans », ????","origine":"Américaine (Alaska)","statut":"« crawler : enders»","affiliations":"« crawler : enders»","mageius_type":"Discella","magie_dominante":"Malédictions","magie_familiale":"Famine de Vhodal","source_group":"Mages","loge":"Autres Loges","identity_keys":["Mila Shelove","Milushka Voroshilov"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Mila Shelove"],["Nom de la Vérité","Milushka Voroshilov"],["Loge","Autres Loges"],["Âge","«46 ans », ????"],["Affiliations","« crawler : enders»"],["Nationalité d’origine","Américaine (Alaska)"],["Nature réelle","Mages (fléau mineur)"],["Type de Mageius","Discella"],["Magie dominante","Malédictions"],["Magie familiale","Famine de Vhodal"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"Miluska est absolument sans pitié, elle voit absolument toutes les créatures comme un repas, peu importe la taille, la forme ou l’amitié nouée avec elle, elle est complétement obsédée par le gout des choses, par le besoin de manger les gens et de savoir quel don ou quelle émotion ils donneront. C’est une drogue pour elle qu’elle cherche à partager à travers le culte de Vhodhal. Elle vénère le Fléau et le considère comme le plus puissant de tous, celui qui peut absolument tout dévorer, la mort, le temps, l’espace, il dévore tout Elle nourrit ses malédictions par la chair de ses victimes…"}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-ryan-foster-33","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Ryan Foster","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Autres Loges","« scientifique » « crawler : meditech »","Mages"],"pnj":{"completeness":"detailed","real_name":"Ryan Foster","nom_verite":"Faust","race":"Mages","age":"«38 ans », ????","origine":"Allemagne","statut":"« scientifique » « crawler : meditech »","affiliations":"« scientifique » « crawler : meditech »","mageius_type":"Anahita","magie_dominante":"Magie spectrale -magie de modelage","magie_familiale":"Magie des Homoncules","source_group":"Mages","loge":"Autres Loges","identity_keys":["Ryan Foster","Faust"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Ryan Foster"],["Nom de la Vérité","Faust"],["Loge","Autres Loges"],["Âge","«38 ans », ????"],["Affiliations","« scientifique » « crawler : meditech »"],["Nationalité d’origine","Allemagne"],["Nature réelle","Mages"],["Type de Mageius","Anahita"],["Magie dominante","Magie spectrale -magie de modelage"],["Magie familiale","Magie des Homoncules"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"Anahita créa un Mageius prodigieux qui donna celui de Merlin, puis elle tenta d’en faire un second, sur la base d’une structure radicalement différente et bien plus chaotique,plus inspirée des Fléaux, elle ne parvint pas à le créer de manière stable, mais laissa ce mageius s’accrocher à la vie. Ce Mageius sordide s’implanta dans Johann Georg Faust, un alchimiste connu pour la légende qu’il engendra. Ce Mage toutefois était bien plus sournois et malfaisant que la version de Goethe notamment. La magie de Faust est la vie, le mouvement, ou plutôt, il est un expert dans la création de pseudo-âmes, en compressant de la Magie originelle. Son but serait toutefois de créer lui aussi des Mageius et d’égaler sa « mère » spirituelle. Créer une âme frôlant le divin, un Mageius frôlant la perfection, un corps immortel, tel est le projet de toute son existence."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-leslie-wright-34","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Leslie Wright","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Autres Loges","« crawler : neopunks»","Mages"],"pnj":{"completeness":"detailed","real_name":"Leslie Wright","nom_verite":"« Merlin »","race":"Mages","age":"«36 ans »","origine":"britannique","statut":"« crawler : neopunks»","affiliations":"« crawler : neopunks»","mageius_type":"Anahita","magie_dominante":"inconnue","magie_familiale":"inconnue","source_group":"Mages","loge":"Autres Loges","identity_keys":["Leslie Wright","« Merlin »"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Leslie Wright"],["Nom de la Vérité","« Merlin »"],["Loge","Autres Loges"],["Âge","«36 ans »"],["Affiliations","« crawler : neopunks»"],["Nationalité d’origine","britannique"],["Nature réelle","Mages"],["Type de Mageius","Anahita"],["Magie dominante","inconnue"],["Magie familiale","inconnue"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"Elle est le plus grand génie de la Terre, certains estiment qu’il est impossible de calculer son QI étant donné les méthodes limitantes actuelles. Elle a révolutionné le monde lors de la guerre, avec l’aide du PCRC. Le paradoxe de Leslie est qu’elle est régulièrement arrêtée par la police pour bagarre, ivresse, atteinte à la pudeur et bien d’autres délits, parfois même des crimes mais aucun jugement ne tombe jamais, tant le gouvernement que les corporations la rendent intouchable, en outre, elle est assez riche pour payer toute condamnation, bien qu’elle ne le fasse jamais elle-même. Récemment, elle a appris sa nature de Mage et a confronté Faust, acceptant d’apprendre de lui, un temps.."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-anahita-35","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Anahita","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Autres Loges","« chasseurs","Mages"],"pnj":{"completeness":"detailed","real_name":"Anahita","nom_verite":"Anahita -","race":"Mages","age":"«XX ans »","origine":"??","statut":"« chasseurs","affiliations":"« chasseurs","mageius_type":"Anahita","magie_dominante":"inconnue","magie_familiale":"inconnue","source_group":"Mages","loge":"Autres Loges","identity_keys":["Anahita","Anahita -"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Anahita"],["Nom de la Vérité","Anahita -"],["Loge","Autres Loges"],["Âge","«XX ans »"],["Affiliations","« chasseurs"],["Nationalité d’origine","??"],["Nature réelle","Mages"],["Type de Mageius","Anahita"],["Magie dominante","inconnue"],["Magie familiale","inconnue"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"Eveillée à un temps très reculé, peu avant la création des Amazones u des Myrmidons, alors que les voyageurs et les dieux s’opposaient, elle semblait déjà présente avant cela, mais en tant que pouvoir plus que conscience. Dotée d’uin corps sensiblement proche du divin en apparence et d’une âme faite de Mageius, elle n’a jamais été d’un camp ou d’un autre. Servante de l’équilibre probablement ou de la magie elle-même, elle a toujours vécu librement, indépendamment et surtout sans jamais se soucier de ce qu’on attendait d’elle. Créatrice curieuse, elle créa deux Mageius d’une nature similaire à la sienne, celui de Merlin et celui de Faust. Elle est l’ultime Mage, l’unique Archimage sur Terre, et les exilés d’Aèr détestent cela, ayant dans leurs rangs"}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-ana-diana-de-la-caza-36","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Ana Diana de la Caza","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Autres Loges","« Créatures »","Abomination - Mage"],"pnj":{"completeness":"detailed","real_name":"Ana Diana de la CAZA","nom_verite":"Anadia","race":"Abomination - Mage","age":"« 79 ans » - 279 ans","origine":"espagnole","statut":"« Créatures »","affiliations":"« Créatures »","mageius_type":"Artificiel","magie_dominante":"inconnue","magie_familiale":"inconnue","source_group":"Mages","loge":"Autres Loges","identity_keys":["Ana Diana de la Caza","Ana Diana de la CAZA","Anadia"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Ana Diana de la CAZA"],["Nom de la Vérité","Anadia"],["Loge","Autres Loges"],["Âge","« 79 ans » - 279 ans"],["Affiliations","« Créatures »"],["Nationalité d’origine","espagnole"],["Nature réelle","Abomination - Mage"],["Type de Mageius","Artificiel"],["Magie dominante","inconnue"],["Magie familiale","inconnue"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"Héritière de la longue lignée d’Ashlutum, elle est une psywitch « black gold », une anomalie aisément expliquée par sa vraie nature d’abomination. En effet, Ana Diana n’est plus humaine depuis longtemps, étant donné qu’elle est la maitresse du culte du « Grand Savoir », elle a restructuré son propre corps pour devenir immortelle et approcher le fonctionnement d’un Mageius. Son Mageius est rudimentaire et fait d’énergie de Sharith, mais il reste unique au monde. Les Mages la détestent car ils ignorent si elle peut en créer d’autres, des « Mageius » de Fléau et ils craignent qu’elle ne rencontre Faust pour ça."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-nike-celio-37","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Nycellyon","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Autres Loges","« crawlers : voidrunner »/ religion","Mages"],"pnj":{"completeness":"detailed","real_name":"Nike Celio","nom_verite":"Nycellyon","race":"Mages","age":"« 50 ans »","origine":"??","statut":"« crawlers : voidrunner »/ religion","affiliations":"« crawlers : voidrunner »/ religion","mageius_type":"Discella","magie_dominante":"magie des ténèbres","magie_familiale":"magie des ténèbres","source_group":"Mages","loge":"Autres Loges","identity_keys":["Nycellyon","Nike Celio"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Nike Celio"],["Nom de la Vérité","Nycellyon"],["Loge","Autres Loges"],["Âge","« 50 ans »"],["Affiliations","« crawlers : voidrunner »/ religion"],["Nationalité d’origine","??"],["Nature réelle","Mages"],["Type de Mageius","Discella"],["Magie dominante","magie des ténèbres"],["Magie familiale","magie des ténèbres"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"Nycellyon est le fils de Discella et d’une incarnation de Diablo, le dieu de la nuit. Ce demi-dieu reçut un Mageius de naissance, avec une affinité croisée, c’est-à-dire que ses trois affinités sont uniquement reliées à la magie ténèbreuses. Il ne peut pas utiliser d’autres magies que celle des ténèbres, des illusions et des malédictions, pas sans passer par des outils ou des sorciers d’autres mages. Il a toujours été un loyal partisan des dieux, servant son père en tant que prêtre mais n’en a jamais reçu les pouvoirs. Ennemi des Mages partisans des loges, il est désormais un prêtre de l’ordre d’Arianwen même s’il n’a pas souvent l’air d’un prêtre. Il est d’une jalousie e d’une haine totale envers le Prêtre Raphael."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-loges-mages-alice-carroll-38","dataset":"verite-loges-mages-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Alice Carroll","source":"factons_Loges des mages(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Mages","Loges des Mages","Autres Loges","« Créatures » - Mage","Rêve- Mage"],"pnj":{"completeness":"detailed","real_name":"Alice Carroll","nom_verite":"Alice","race":"Rêve- Mage","age":"«20 ans » - ???","origine":"britannique","statut":"« Créatures » - Mage","affiliations":"« Créatures » - Mage","mageius_type":"Discella","magie_dominante":"magie des illusions","magie_familiale":"Empire des rêves","source_group":"Mages","loge":"Autres Loges","identity_keys":["Alice Carroll","Alice"]},"sections":[{"id":"profil-loges-mages","title":"Profil magique · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom de la Réalité","Alice Carroll"],["Nom de la Vérité","Alice"],["Loge","Autres Loges"],["Âge","«20 ans » - ???"],["Affiliations","« Créatures » - Mage"],["Nationalité d’origine","britannique"],["Nature réelle","Rêve- Mage"],["Type de Mageius","Discella"],["Magie dominante","magie des illusions"],["Magie familiale","Empire des rêves"]]}]},{"id":"informations-mj-loges-mages","title":"Informations MJ · Loges des Mages","level":2,"audience":"mj","blocks":[{"type":"p","style":"lore","text":"On ignore son nom et son âge, son identité ou ce qu’elle était, peut être un voyageur, peut-être une elfe, impossible de savoir. Cette âme a été prisonnières des rêves, jetée par un fléau. Elle y a dévoré un Mageius et de nombreux « rêves », les créatures créées par l’imaginaire afin de survivre. Ds millions d’aventures et de vies passées dans les rêves, elle a réussi à en sortir en 1860, sous l’apparence d’une jeune fille blonde, recueillie par Lewis Carroll. Il s’en inspira pour « Les Aventures d'Alice au pays des merveilles », même si le récit d’Alice n’avait rien de merveilleux en soi. Déconnectée, c’est une des mages les plus puissantes du monde, peut-être la plus puissante après Anahita, puisqu’elle peut créer tout ce que les gens autour d’elle imagine, elle ne peut rien créer qu’elle n’a elle-même en tête, mais il suffit de le suggérer ou le décrire et quelqu’un va le faire. Elle est indépendante et déteste les autres mages et inhumains. Elle mène une vie d’errance, sans vrai but."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]}] as Array<Record<string, any>>;
